def _apply_intro_programming_lessons(package: dict[str, Any]) -> None:
    """Replace generic seed text with a coherent beginner Python sequence."""
    for group in package.get("groups", []):
        if group.get("key") != "intro_programming":
            continue
        for block in group.get("blocks", []):
            lesson = INTRO_PROGRAMMING_LESSONS.get(block.get("task_number"))
            if lesson:
                block.update({
                    **lesson,
                    "content": _compose_intro_programming_content(block.get("task_number"), lesson["content"]),
                })


